instrument ILL_D2B {
  // Instrument parameters
  parameter double lambda = 1.594;
  parameter double DM = 0;
  parameter string Powder = "Na2Ca3Al2F14.laz";
  parameter double RV = -1;
  parameter double L1 = 16.05;
  parameter double L2 = 2.645;
  parameter double L3 = 1.3;
  parameter int verbose = 1;
  parameter double ALPHA1 = 18;
  parameter double ALPHA2 = 11;
  parameter double ALPHA3 = 5;
  parameter double ETA = 12;
  parameter double THETA_M = 67.5;
  parameter double TILT = 0;
  parameter double SM = 1;
  parameter double Dheight = 0.3;
  parameter double coating = 0;

  // Constants
  const double DEG2RAD = 0.017453292519943295;
  const double RAD2DEG = 57.29577951308232;
  const double K2V = 3956.0; // m/s per 1/Å
  const double VS2E = 0.00138929448194; // meV per (m/s)^2

  // Derived quantities
  double L;
  double KI, Vi, EI;
  double ALPHA3_Opt;
  double U, V, W, L0;

  // Compute derived quantities
  if (THETA_M == 0 && lambda != 0 && DM != 0) {
    THETA_M = asin(lambda / (2 * DM)) * RAD2DEG;
  } else if (THETA_M != 0 && lambda == 0 && DM != 0) {
    lambda = 2 * DM * sin(THETA_M * DEG2RAD);
  } else if (THETA_M != 0 && lambda != 0) {
    DM = lambda / (2 * sin(THETA_M * DEG2RAD));
  }

  THETA_M *= SM;

  if (THETA_M == 0 || DM == 0 || lambda == 0) {
    exit(fprintf(stderr, "ILL_D2B: ERROR: Monochromator take-off, d-spacing or wavelength is null (THETA_M=%g, DM=%g, lambda=%g). Abort.\n", THETA_M, DM, lambda));
  }

  if (L1 != 0) {
    L = 1 / (1 / L1 + 1 / L2);
  } else {
    L = L2;
  }

  if (RV < 0) {
    RV = 2 * L * sin(THETA_M * DEG2RAD);
  }

  KI = 2 * PI / lambda;
  Vi = K2V * KI;
  EI = VS2E * Vi * Vi;

  if (ALPHA1 < 0) ALPHA1 = 600;
  if (ALPHA2 < 0) ALPHA2 = 600;
  if (ALPHA3 < 0) ALPHA3 = 600;
  if (ETA <= 0) ETA = 30;

  U = 4 * (ALPHA1 * ALPHA1 * ALPHA2 * ALPHA2 + ALPHA1 * ALPHA1 * ETA * ETA + ALPHA2 * ALPHA2 * ETA * ETA) / (tan(THETA_M * DEG2RAD) * tan(THETA_M * DEG2RAD) * (ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA));
  V = 4 * ALPHA2 * ALPHA2 * (ALPHA1 * ALPHA1 + 2 * ETA * ETA) / (tan(THETA_M * DEG2RAD) * (ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA));
  W = ALPHA3 * ALPHA3 + (ALPHA1 * ALPHA1 * ALPHA2 * ALPHA2 + 4 * ALPHA2 * ALPHA2 * ETA * ETA) / (ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA);
  L0 = (ALPHA1 * ETA * ALPHA2 * ALPHA3 / tan(fabs(THETA_M) * DEG2RAD)) / sqrt(ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA);
  ALPHA3_Opt = 1 / sqrt(1 / (ALPHA1 * ALPHA1) + 1 / (ALPHA2 * ALPHA2) + 1 / (ETA * ETA));

  if (verbose) {
    printf("ILL_D2B: Detailed DIF configuration\n");
    printf("* Incoming beam: lambda=%.4g [Angs] EI=%.4g [meV]  KI=%.4g [Angs-1] Vi=%g [m/s]\n", lambda, EI, KI, Vi);
    printf("* Monochromator:  DM=%.4g [Angs] RV=%.4g [m] %s, take-off 2*THETA_M=%.4g [deg]\n", DM, RV, (RV == 0 ? "flat" : "curved"), 2 * THETA_M);
    printf("* Resolution:     Caglioti              U=%g V=%g W=%g [deg^2]\n", U / 3600, V / 3600, W / 3600);
    printf("                  Optimal          ALPHA3=%g [min]\n", ALPHA3_Opt);
    printf("                  Optimal resolution A1/2=%g [min]\n", ALPHA3_Opt / sqrt(2));
    printf("                  Normalized Intensity L0=%g [min^3]\n", L0);
  }

  // Wavelength options for monitors
  string lamopts = "lambda limits=[%g, %g]", lambda * 0.99, lambda * 1.01;

  // Components
  Progress_bar Origin at (0, 0, 0) rotated (0, 0, 0);

  Source_gen Source at (0, 0, 0) relative Origin rotated (0, 0, 0) {
    radius = 0.11;
    dist = 11;
    focus_xw = fabs(0.05 * sin(THETA_M * DEG2RAD));
    focus_yh = 0.3;
    lambda0 = lambda;
    dlambda = lambda * 0.01;
    I1 = 0.5874e+13;
    T1 = 683.7;
    I2 = 2.5099e+13;
    T2 = 257.7;
    I3 = 1.0343e+12;
    T3 = 16.7;
  }

  Slit Win0 at (0, 0, 2.462) relative Origin rotated (0, 0, 0) {
    radius = 0.11;
  }

  Slit Oct1 at (0, 0, 2.512) relative Origin rotated (0, 0, 0) {
    xwidth = 0.15;
    yheight = 0.15;
  }

  Slit Oct2 at (0, 0, 2.512) relative Origin rotated (0, 0, 45) {
    xwidth = 0.177;
    yheight = 0.177;
  }

  Slit Win1 at (0, 0, 3.5321) relative Origin rotated (0, 0, 0) {
    radius = 0.0565;
  }

  Slit Win2 at (0, 0, 4.0421) relative Origin rotated (0, 0, 0) {
    radius = 0.0555;
  }

  Slit Win3 at (0, 0, 4.087) relative Origin rotated (0, 0, 0) {
    radius = 0.0575;
  }

  Slit Win4 at (0, 0, 4.999) relative Origin rotated (0, 0, 0) {
    radius = 0.0575;
  }

  Slit Win5 at (0, 0, 5.006) relative Origin rotated (0, 0, 0) {
    radius = 0.0625;
  }

  Slit Win6 at (0, 0, 5.151) relative Origin rotated (0, 0, 0) {
    radius = 0.0625;
  }

  if (coating > 0) {
    Guide SMguide at (0, 0, 11) relative Origin rotated (0, 0, 0) {
      w1 = 0.07;
      h1 = 0.3;
      l = 5;
      m = coating;
    }
  }

  if (ALPHA1 > 0) {
    Collimator_linear Alpha_One at (0, 0, L1 - 1.045) relative Origin rotated (0, 0, 0) {
      xwidth = 0.07;
      yheight = 0.30;
      length = 0.70;
      divergence = ALPHA1;
      transmission = 1.0;
    }
  }

  Slit Slit_Mono at (0, 0, L1 - 0.1) relative Origin rotated (0, 0, 0) {
    xwidth = 0.05;
    yheight = 0.3;
  }

  Monitor_nD D2B_Mono_XY at (0, 0, 0) relative Slit_Mono rotated (0, 0, 0) {
    xwidth = 0.1;
    yheight = 0.3;
    bins = 40;
    restore_neutron = 1;
    options = "x y";
  }

  Monitor_nD D2B_ALPHA1_Div at (0, 0, 0) relative D2B_Mono_XY rotated (0, 0, 0) {
    xwidth = 0.1;
    yheight = 0.3;
    bins = 40;
    restore_neutron = 1;
    options = "dx limits=[-0.5 0.5] dy limits=[-1 1]";
  }

  Monitor_nD D2B_Mono_Lambda at (0, 0, 0) relative D2B_ALPHA1_Div rotated (0, 0, 0) {
    xwidth = 0.1;
    yheight = 0.3;
    bins = 40;
    restore_neutron = 1;
    options = lamopts;
  }

  Arm mono_cradle at (0, 0, L1) relative Origin rotated (0, 0, 0);

  Monochromator_curved Monok at (0, 0, 0) relative mono_cradle rotated (0, THETA_M + TILT, 0) {
    NH = 1;
    NV = 28;
    mosaich = ETA;
    mosaicv = 12;
    RV = RV;
    DM = DM;
    width = 0.1;
    height = 0.3;
  }

  PSD_monitor_4PI sphere at (0, 0, 0) relative mono_cradle rotated (0, 0, 0) {
    filename = "sphere";
    radius = 0.5;
    restore_neutron = 1;
  }

  Arm mono_out at (0, 0, 0) relative mono_cradle rotated (0, 2 * THETA_M, 0);

  Guide_channeled Shield_Hole at (0, 0, 0.304) relative mono_out rotated (0, 0, 0) {
    w1 = 0.05;
    h1 = 0.274;
    w2 = 0.044;
    h2 = 0.201;
    l = 0.752;
    R0 = 0;
    nslit = 1;
  }

  if (ALPHA2 > 0) {
    Collimator_linear Alpha_Two at (0, 0, L2 - 0.25) relative mono_out rotated (0, 0, 0) {
      xwidth = 0.05;
      yheight = 0.2;
      length = 0.2;
      divergence = ALPHA2;
      transmission = 1.0;
    }
  }

  Slit Slit_Sample at (0, 0, L2 - 0.02) relative mono_out rotated (0, 0, 0) {
    xwidth = 0.01;
    yheight = 0.05;
  }

  Monitor_nD D2B_ALPHA2_Div at (0, 0, 0) relative Slit_Sample rotated (0, 0, 0) {
    xwidth = 0.02;
    yheight = 0.05;
    bins = 40;
    restore_neutron = 1;
    options = "dx limits=[-0.5 0.5] dy limits=[-1 1]";
  }

  Monitor_nD D2B_Sample_Lambda at (0, 0, 0) relative D2B_ALPHA2_Div rotated (0, 0, 0) {
    xwidth = 0.02;
    yheight = 0.05;
    bins = 40;
    restore_neutron = 1;
    options = lamopts;
  }

  Arm Arm_Sample at (0, 0, L2) relative mono_out rotated (0, 0, 0);

  PowderN Container_in at (0, 0, 0) relative Arm_Sample rotated (0, 0, 0) {
    reflections = "V.lau";
    radius = 0.0025 + 0.00051;
    yheight = 0.04;
    thickness = 0.0005;
    d_phi = atan2(Dheight + 0.05, L3) * RAD2DEG;
    p_interact = 0.1;
    concentric = 1;
  }

  PowderN Sample at (0, 0, 0) relative Arm_Sample rotated (0, 0, 0) {
    reflections = Powder;
    radius = 0.0025;
    yheight = 0.04;
    d_phi = atan2(Dheight + 0.05, L3) * RAD2DEG;
  }

  PowderN Container_out at (0, 0, 0) relative Arm_Sample rotated (0, 0, 0) {
    reflections = "V.lau";
    radius = 0.0025 + 0.00051;
    yheight = 0.04;
    thickness = 0.0005;
    d_phi = atan2(Dheight + 0.05, L3) * RAD2DEG;
    p_interact = 0.1;
    concentric = 1;
  }

  if (ALPHA3 > 0) {
    Collimator_radial collimador_radial at (0, 0, 0) relative Sample rotated (0, 0, 0) {
      yheight = Dheight;
      length = 0.30;
      divergence = ALPHA3;
      theta_min = -165;
      theta_max = -5;
      radius = L3 - 0.3 - 0.01;
      verbose = 1;
      approx = 1;
    }
  }

  Monitor_nD D2B_BananaTheta at (0, 0, 0) relative Sample rotated (0, 0, 0) {
    yheight = Dheight;
    restore_neutron = 1;
    radius = L3;
    options = "banana, angle limits=[5 165], bins=3200";
  }

  Monitor_nD D2B_BananaThetaCenter at (0, 0, 0) relative Sample rotated (0, 0, 0) {
    yheight = 0.1;
    restore_neutron = 1;
    radius = L3;
    options = "banana, angle limits=[5 165], bins=3200";
  }

  Monitor_nD D2B_BananaPSD at (0, 0, 0) relative Sample rotated (0, 0, 0) {
    yheight = Dheight;
    radius = L3 * 1.005;
    options = "banana, theta limits=[-165 -5] bins=320, y bins=25";
  }

  // Run the instrument
  run {
    ncount = 1e6;
    seed = 123456;
    gravity = true;
  }
}
